from fastapi import Depends, FastAPI, Header, HTTPException

app = FastAPI()

def require_api_key(x_api_key: str | None = Header(default=None)) -> str:
    if x_api_key != 'devquest-secret':
        raise HTTPException(status_code=401, detail='Invalid API key')
    return x_api_key

@app.get('/whoami')
def whoami(key: str = Depends(require_api_key)):
    return {'authenticated': True}

from fastapi import Request
from fastapi.responses import JSONResponse

@app.exception_handler(QuotaExceededError)
async def quota_handler(request: Request, exc: QuotaExceededError):
    return JSONResponse(status_code=429, content={'error': 'quota_exceeded', 'limit': exc.limit})

@app.middleware('http')
async def add_service_header(request: Request, call_next):
    response = await call_next(request)
    response.headers['X-Service'] = 'devquest'
    return response

