from contextlib import contextmanager
from functools import wraps

def log_calls(fn):
    @wraps(fn)
    def wrapper(*args, **kwargs):
        return fn(*args, **kwargs)
    return wrapper

@contextmanager
def scoped_tag(events, tag):
    events.append(f'enter:{tag}')
    try:
        yield
    finally:
        events.append(f'exit:{tag}')

import asyncio

async def fetch_all(factories):
    return list(await asyncio.gather(*(fn() for fn in factories)))

