export function useFilteredFeed(items, query) {
  return React.useMemo(() => {
    const q = query.trim().toLowerCase();
    const visible = q ? items.filter((it) => it.text.toLowerCase().includes(q)) : items;
    return { visible, total: items.length, hidden: items.length - visible.length };
  }, [items, query]);
}

