import assert from 'node:assert/strict';
import React from 'react';
import { renderToStaticMarkup } from 'react-dom/server';
import { LiveFeed, subscribeWithCleanup, useFilteredFeed } from './LiveFeed.mjs';

// 1. Verify subscription + cleanup teardown
let active = 0;
let lastChannel = null;
const bus = {
  subscribe(ch, cb) {
    active += 1;
    lastChannel = ch;
    cb && cb('ping');
    return () => { active -= 1; };
  },
};
let received = null;
const cleanup = subscribeWithCleanup(bus, 'evals', (e) => { received = e; });
assert.equal(active, 1);
assert.equal(lastChannel, 'evals');
assert.equal(received, 'ping');
cleanup();
assert.equal(active, 0);
assert.equal(typeof subscribeWithCleanup(null, 'evals', null), 'function');

// 2. Verify custom hook + SSR rendering with filter
const items = [
  { id: 1, text: 'Epoch 1 Loss 0.42', level: 'info' },
  { id: 2, text: 'CUDA OOM warning', level: 'warn' },
  { id: 3, text: 'Epoch 2 Loss 0.21', level: 'info' },
];
const htmlFiltered = renderToStaticMarkup(
  React.createElement(LiveFeed, { items, query: '  epoch ', channel: 'train' })
);
assert.match(htmlFiltered, /class="live-feed"/);
assert.match(htmlFiltered, /data-channel="train"/);
assert.match(htmlFiltered, /data-count="2"/);
assert.match(htmlFiltered, /2 of 3 shown \(1 hidden\)/);
assert.match(htmlFiltered, /<li data-level="info">Epoch 1 Loss 0\.42<\/li>/);
assert.match(htmlFiltered, /<li data-level="info">Epoch 2 Loss 0\.21<\/li>/);
assert.doesNotMatch(htmlFiltered, /CUDA OOM/);

// 3. Verify empty state
const htmlEmpty = renderToStaticMarkup(
  React.createElement(LiveFeed, { items, query: 'nonexistent', channel: 'train' })
);
assert.match(htmlEmpty, /0 of 3 shown \(3 hidden\)/);
assert.match(htmlEmpty, /<p class="empty">No matching events<\/p>/);

// 4. Verify hook directly inside a probe component
let probed = null;
function Probe() {
  probed = useFilteredFeed(items, 'oom');
  return null;
}
renderToStaticMarkup(React.createElement(Probe));
assert.deepEqual(probed, { visible: [items[1]], total: 3, hidden: 2 });
console.log('React custom hook & cleanup tests passed!');
